["Entangles an enemy in a corrosive web, immobilizing them and dealing Nature damage over 4 sec."]="將敵人纏在腐蝕網中，使其無法動彈，並在 4 秒內造成自然傷害。",
["Enter Blackrock Depths and track down Lord Incendius. Slay him and return any source of information you may find to Thunderheart. "]="進入黑石深淵並追蹤 Incendius 領主。殺死他並將你找到的任何資訊來源歸還給雷霆之心。",
["Enter Dire Maul East through the Broken Commons; Pusillin waits near the entrance."]="透過破碎公地進入厄運之槌東區；普西林在入口處等候。",
["Ephemeral Grips"]="短暫之握",
["Erudite's Amulet"]="博學者的護身符",
["Escape Plan"]="逃亡計劃",
["Escort your prisoner, Grark Lorkrub, through Burning Steppes and through Blackrock Mountain to the Searing Gorge.  You recall Lexlort mentioning that he would have his men waiting on the other side to take Grark into custody.  You will also be required to hand over your Thorium Shackles to Lexlort."]="護送你的囚犯格拉克·洛克魯布穿過燃燒平原，穿過黑石山到達灼熱峽谷。  你記得萊克斯洛特提到過他會讓他的手下在另一邊等著拘留格拉克。  您還需要將瑟銀鐐銬交給萊克斯洛特。",
