["Field Researcher's Loop"]="現場研究員迴圈",
["Find Ardin Grassman in the Excavation Sites."]="在挖掘地點找到阿丁草人。",
["Find Bijou's Belongings and return them to her. Good luck! "]="找到比茹的物品並將其歸還給她。祝你好運！",
["Find Duskwing and slay him. From the corpse, recover a Patch of Duskwing's Fur and return it to Nathanos Blightcaller.  It is said that Duskwing roams the countryside to the north of Marris Stead."]="找到暮翼並殺死他。從屍體上找到一塊暮翼毛皮並將其歸還給納薩諾斯·凋零者。  據說暮翼在馬里斯斯特德北部的鄉村中漫步。",
["Find The Horn of Xelthos inside of Shadowfang Keep. Then, return it to C's dead drop near Pyrewood Village. You must complete the job alone."]="在影牙要塞內找到塞爾索斯號角。然後，將其送回焚木村附近 C 的死亡地點。你必須獨自完成這項工作。",
["Find a way into Dalaran along the Lordamere Lake."]="沿著洛丹米爾湖找到進入達拉然的路。",
["Find the forge hidden in the Deadmines, and plant the Extra-Destructive Explosives nearby. Then, meet up with Alba Fairmoon at the Deadmines exit."]="找到隱藏在死亡礦井中的熔爐，並在附近放置超殺傷性炸藥。然後，在死亡礦井出口與阿爾巴·費爾月會面。",
["Find the owner of the Feathered Charm Necklace."]="找到羽毛吊飾項鍊的主人。",
["Find the ruby, sapphire, and topaz that are scattered throughout Uldaman. Once acquired, contact Talvash del Kissel remotely by using the Phial of Scrying he previously gave you.  From the journal, you know... * The ruby has been stashed in a barricaded Shadowforge area. * The topaz has been hidden in an urn in one of the Trogg areas, near some Alliance dwarves.  * The sapphire has been claimed by Grimlok, the trogg leader."]="尋找散佈在奧達曼各地的紅寶石、藍寶石和黃玉。獲得後，使用塔爾瓦什·德爾·基塞爾之前給你的占卜瓶遠端聯絡他。  從日記中，你知道... * 紅寶石被藏在一個設有路障的暗爐區域。 * 黃玉被藏在穴居人地區之一的甕中，靠近一些聯盟矮人。  * 藍寶石已被穴居人首領格里姆洛克奪取。",
["Find the three gemstones of command: The Gemstone of Smolderthorn, Gemstone of Spirestone, and Gemstone of Bloodaxe. Return them, along with the Unadorned Seal of Ascension, to Vaelan.  The Generals, as told to you by Vaelan, are: War Master Voone of the Smolderthorn; Highlord Omokk of the Spirestone; and Overlord Wyrmthalak of the Bloodaxe."]="找到三顆指揮寶石：悶棘寶石、尖石寶石和血斧寶石。將它們連同樸素的昇天印章一起歸還給維蘭。  正如維蘭告訴你的那樣，將軍們是： 悶燃棘的戰爭大師沃恩；尖石大領主奧莫克；以及血斧霸主維姆薩拉克。",
