["Take the Skeleton Key Mold and 2 Thorium Bars to the top of Fire Plume Ridge in Un'Goro Crater. Use the Skeleton Key Mold by the lava lake to forge the Unfinished Skeleton Key.  Bring the Unfinished Skeleton Key to Alchemist Arbington at Chillwind Point, Western Plaguelands."]="將萬能鑰匙模具和 2 瑟銀錠帶到安戈洛環形山的火羽嶺頂部。使用熔岩湖邊的萬能鑰匙模具來鍛造未完成的萬能鑰匙。  將未完成的萬能鑰匙交給西瘟疫之地寒風點的鍊金術士阿爾賓頓。",
["Take the Skeleton Key Mold and 2 Thorium Bars to the top of Fire Plume Ridge in Un'Goro Crater. Use the Skeleton Key Mold by the lava lake to forge the Unfinished Skeleton Key.  Bring the Unfinished Skeleton Key to Apothecary Dithers at the Bulwark, Western Plaguelands."]="將萬能鑰匙模具和 2 瑟銀錠帶到安戈洛環形山的火羽嶺頂部。使用熔岩湖邊的萬能鑰匙模具來鍛造未完成的萬能鑰匙。  將未完成的萬能鑰匙交給西瘟疫之地壁壘的藥劑師迪瑟斯。",
