["Travel to Blackrock Depths and find Kharan Mighthammer.  The King mentioned that Kharan was being held prisoner there - perhaps you should try looking for a prison."]="前往黑石深淵並找到卡蘭·巨錘。  國王提到卡蘭被關押在那裡——也許你應該嘗試尋找一所監獄。",
["Travel to Blackrock Depths and recover 10 Essence of the Elements. Your first inclination is to search the golems and golem makers. You remember Vivian Lagrave also muttering something about elementals. "]="前往黑石深淵並恢復 10 元素精華。你的第一反應是搜尋傀儡和傀儡製造者。你記得維維安·拉格雷夫也曾嘀咕過一些關於元素的事情。",
["Travel to Blackrock Depths and recover 20 Dark Iron Fanny Packs. Return to Oralius when you have completed this task. You assume that the Dark Iron dwarves inside Blackrock Depths carry these 'fanny pack' contraptions. "]="前往黑石深淵並找回 20 黑鐵腰包。完成此任務後返回奧拉流斯。你假設黑石深淵內的黑鐵矮人攜帶這些“腰包”裝置。",
["Travel to Blackrock Depths and slay Bael'Gar.  You only know that the giant resides inside Blackrock Depths. Remember to use the Altered Black Dragonflight Molt on Bael'Gar's remains to capture the Fiery Essence.  Return the Encased Fiery Essence to Cyrus Therepentous.  "]="前往黑石深淵並殺死巴爾加爾。  你只知道巨人居住在黑石深淵內。記得在巴爾加爾的遺骸上使用變異黑龍軍團蛻皮來獲取熾熱精華。  將封裝的火焰精華歸還給賽勒斯·泰彭託斯。",
["Travel to Stormwind and deliver Solomon's Plea to Highlord Bolvar Fordragon.  Bolvar resides in Stormwind Keep."]="前往暴風城，將所羅門的懇求交給大領主伯瓦爾·弗塔根。  伯瓦爾居住在暴風要塞。",
["Travel to the Burning Steppes and find Grark Lorkrub. You recall Lexlort mentioning that he was last seen in a massive Blackrock fortress.  When you find Grark Lorkrub, use the Thorium Shackles to bind him and then lead him back through Blackrock Mountain to the Searing Gorge. Lexlort will have his men waiting on the other side to take Grark into custody. "]="前往燃燒平原並找到格拉克·洛克魯布。你還記得萊克斯洛特提到過他最後一次出現是在一座巨大的黑石要塞中。  當你找到格拉克·洛克魯布時，使用瑟銀鐐銬束縛他，然後帶他穿過黑石山回到灼熱峽谷。萊克斯洛特將讓他的手下在另一邊等待，以拘留格拉克。",
["Travel to the Dwarven District in Stormwind and find an engineer who can help."]="前往暴風城的矮人區，尋找可以提供幫助的工程師。",
["Travel to the Wetlands and meet the Deathstalker Agent in the hills above the Dragonmaw camp."]="前往溼地並在龍喉營地上方的山上與死亡獵手會面。",
["Travel to the Wyrmbog in Dustwallow Marsh and seek out Emberstrife's Den. Once inside, wear the Amulet of Draconic Subversion and speak with Emberstrife. "]="前往塵泥沼澤的龍沼並尋找安伯斯特萊夫的巢穴。進入後，佩戴龍語顛覆護身符並與 Emberstrife 交談。",
["Travel to the Wyrmbog in Dustwallow Marsh. Find the ancient drake, Emberstrife and beat him without mercy until his will is broken.  It is at that moment which you must place the Unforged Seal of Ascension before the great beast. You must then be quick to use the Orb of Draconic Energy on his weakened form and claim dominion over his mental faculties. Control the beast and force the Flames of the Black Dragonflight upon the Unforged Seal of Ascension!"]="前往塵泥沼澤的龍沼。找到古老的龍，Emberstrife，毫不留情地毆打他，直到他的意志被打破。  正是在那一刻，你必須將未鍛造的昇天印章放在巨獸面前。然後你必須迅速對他虛弱的形態使用龍之能量球，並聲稱對他的精神能力有統治權。控制這頭野獸，將黑龍軍團的火焰強加到未鍛造的飛昇封印上！",
["Travel to the northern borders of the Eastern Plaguelands and recover the Quel'Thalas Registry. The item is somewhere in the Quel'Lithien lodge.  You must also slay 8 Rangers, 8 Pathstriders, and 8 Woodsmen."]="前往東瘟疫之地的北部邊界並恢復奎爾薩拉斯登記處。該物品位於奎爾利西安小屋的某處。  您還必須殺死 8 遊騎兵、8 行者和 8 伐木人。",
