["Use: Breathe dragonfire in a narrow cone, dealing 450 Fire damage immediately and 125 every 2 sec for 8 sec. 2 min cooldown."]="使用：在狹窄的錐形範圍內噴出龍火，立即造成 450 點火焰傷害，並在 8 秒內每 2 秒造成 125 點傷害。冷卻時間 2 分鐘。",
["Use: Gain 10 charges of Venomous Blood for 20 sec. When you take bleed damage, a charge jumps to an enemy within 8 yd and deals 325 Nature damage when it expires. 2 min cooldown."]="使用：獲得 10 層毒血，持續 20 秒。受到流血傷害時，1 層效果跳至 8 碼內的敵人身上，並在到期時造成 325 點自然傷害。冷卻時間 2 分鐘。",
["Use: Increases attack power by 14 for 30 sec. Shares the potion cooldown."]="使用: 攻擊強度增加 14，持續 30 秒。共享藥水冷卻時間。",
["Use: Increases attack power by 40 for 30 sec. Shares the potion cooldown."]="使用: 攻擊強度增加 40，持續 30 秒。共享藥水冷卻時間。",
["Use: Increases healing by 28 for 30 sec. Shares the potion cooldown."]="使用: 增加 28 治療效果，持續 30 秒。共享藥水冷卻時間。",
["Use: Increases healing by 75 for 30 sec. Shares the potion cooldown."]="使用: 增加 75 治療效果，持續 30 秒。共享藥水冷卻時間。",
["Use: Increases spell damage by 14 for 30 sec. Shares the potion cooldown."]="使用: 增加法術傷害 14，持續 30 秒。共享藥水冷卻時間。",
["Use: Increases spell damage by 265 against elementals for 2 min. 2 min cooldown."]="使用：對元素生物造成的法術傷害提高 265 點，持續 2 分鐘。冷卻時間 2 分鐘。",
["Use: Increases spell damage by 40 for 30 sec. Shares the potion cooldown."]="使用: 增加法術傷害 40，持續 30 秒。共享藥水冷卻時間。",
["Use: Throw a caustic cloud lasting 12 sec; enemies inside take 285-315 Nature damage each second. 2 min cooldown."]="使用：投擲一團持續 12 秒的腐蝕雲，雲中的敵人每秒受到 285-315 點自然傷害。冷卻時間 2 分鐘。",
["Use: Throw a cloud that lasts 8 sec; enemies inside have 15% reduced chance to hit. 2 min cooldown."]="使用：投擲一團持續 8 秒的煙霧，煙霧內敵人的命中機率降低 15%。冷卻時間 2 分鐘。",
["Using the Beacon Torch, mark each tower in Andorhal; you will need to stand in the doorway of the tower to successfully mark it.  Once all four towers are marked, return the Beacon Torch to Commander Ashlam Valorfist in Chillwind Camp, Western Plaguelands."]="使用信標火炬標記安多哈爾的每座塔；您需要站在塔的門口才能成功標記它。  一旦所有四座塔都被標記，將信標火炬歸還給西瘟疫之地寒風營地的指揮官阿什拉姆·瓦洛菲斯特。",
["Using the Beacon Torch, mark each tower in Andorhal; you will need to stand in the doorway of the tower to successfully mark it.  Once all four towers are marked, return the Beacon Torch to High Executor Derrington at the Bulwark, Western Plaguelands."]="使用信標火炬標記安多哈爾的每座塔；您需要站在塔的門口才能成功標記它。  一旦所有四座塔都被標記，將信標火炬歸還給西瘟疫之地壁壘的高階執行官德林頓。",
