["Venture to Blackrock Depths and destroy the vile aggressors!  Warlord Goretooth wants you to kill 10 Anvilrage Medics, 10 Anvilrage Soldiers and 10 Anvilrage Officers. Return to him once your task is complete."]="前往黑石深淵並消滅邪惡的侵略者！  軍閥戈圖斯希望你殺死 10 鐵怒醫療兵、10 鐵怒士兵和 10 鐵怒軍官。任務完成後回到他身邊。",
["Venture to Blackrock Depths and destroy the vile aggressors!  Warlord Goretooth wants you to kill 15 Anvilrage Guardsmen, 10 Anvilrage Wardens and 5 Anvilrage Footmen. Return to him once your task is complete.  "]="前往黑石深淵並消滅邪惡的侵略者！  軍閥戈圖斯希望你殺死 15 鐵怒衛兵、10 鐵怒守衛者和 5 鐵怒步兵。任務完成後回到他身邊。",
["Venture to the Burning Steppes and recover 10 Fractured Elemental Shards for Hierophant Theodora Mulvadania.  You recall Theodora mentioning the golems and elementals of that region as being a source for these shards."]="前往燃燒平原冒險，為聖職者西奧多拉·馬爾瓦達尼亞找回 10 破碎的元素碎片。  你記得西奧多拉提到過該地區的傀儡和元素是這些碎片的來源。",
