["Veyric Thunderhame"]="威裡克·雷哈姆",
["Viciously bites enemy appendages for damage and reduces the effectiveness of any healing by 50% for 10 sec."]="惡毒地咬住敵人的肢體造成傷害，並降低 50% 的治療效果，持續 10 秒。",
["Vigilant Watcher's Signet"]="警惕守護者徽記",
["Violet Sash"]="紫羅蘭腰帶",
["Violet Sorcerer's Leggings"]="紫羅蘭巫師護腿",
["Violet Sorcerer's Mantle"]="紫羅蘭巫師襯肩",
["Violet Sorcerer's Robes"]="紫羅蘭魔法師長袍",
["Violet Sorcerer's Sandals"]="紫羅蘭巫師涼鞋",
["Violet Sorcerer's Wraps"]="紫羅蘭巫師裹腕",
["Viridian Dye"]="常綠染料",
["Volunteer's Lucky Seal"]="志願者的幸運印章",
["Vuldren"]="沃爾德倫",
["Vuldren Alpha"]="沃爾德倫阿爾法",
["Vulgara the Insatiable"]="貪得無厭的沃加拉",
["WANTED"]="通緝",
["Wailing Caverns (Dungeon)"]="哀嚎洞穴（地下城）",
["Wait for Kalaran Windblade to complete the Torch of Retribution. "]="等待卡拉蘭風刃完成懲戒火炬。",
["Walter Mason"]="沃爾特·梅森",
["Warcaller Gorlach"]="戰爭召喚者戈爾拉克",
["Warden Thelwater"]="典獄長塞爾沃特",
["Warder's Belt"]="守衛腰帶",
["Warder's Boots"]="守衛的靴子",
["Warder's Gauntlet"]="守衛的手套",
["Warder's Gloves"]="守衛手套",
["Warder's Pauldrons"]="守望者肩甲",
["Warder's Sabatons"]="守衛馬靴",
["Warder's Waistguard"]="守衛護腰",
["Warder's Wristguards"]="守望者護腕",
["Warlord Goretooth"]="軍閥戈圖斯",
["Warpwood Quarter of the ancient Highborne city of Eldre'Thalas, overgrown by corrupted ancients and satyrs. Alzzin the Wildshaper tends the Felvine."]="古老的上層精靈城市艾德雷薩拉斯的經木區，長滿了腐化的古人和薩特。狂野塑造者阿爾辛照料著邪藤。",
["Western Plaguelands"]="西瘟疫之地",
["Westfall"]="西部荒野",
["Westfall, Moonbrook"]="西部荒野、月溪",
["Wetlands"]="溼地",
["Whimsical Waistwrap"]="異想天開的腰帶",
["Wicked Smoothie"]="邪惡的冰沙",
["Wild Malleus"]="野生錘狀體",
["Wildstalker's Breastplate"]="狂野追獵者的胸甲",
["Wildstalker's Gauntlets"]="狂野追獵者護手",
["Wildstalker's Greaves"]="狂野追獵者護腿",
["Wildstalker's Helm"]="狂野追獵者頭盔",
["Wildstalker's Legguards"]="狂野追獵者護腿",
["Wildstalker's Spaulders"]="狂野追獵者肩甲",
["Wiley the Black"]="黑人威利",
["William Pickman"]="威廉·皮克曼",
["Windsong Crawler"]="風歌爬行者",
["Winklespark"]="溫克斯帕克",
["Winterspring"]="冬泉谷",
["Wisdom of Ursol"]="烏索爾的智慧",
["Wisdom's Leather Armor"]="智慧的皮甲",
["Wisdom's Leather Helm"]="智慧的皮頭盔",
["Witch Doctor Uzer'i"]="巫醫烏澤伊",
["Withering Grips"]="枯萎之握",
["Wolfsbane"]="狼毒",
["Woodwyrd"]="伍德沃德",
["Woolen Tourniquet"]="羊毛止血帶",
["Wrex's Pinky Ring"]="雷克斯的小指戒指",
["Yeh'kinya"]="葉基尼亞",
["Yorba Screwspigot"]="約巴螺絲釘",
["You must destroy the guardians surrounding the 5 Pylons that power the Prison of Immol'thar. Once the Pylons have powered down, the force field surrounding Immol'thar will have dissipated.  Enter the Prison of Immol'thar and eradicate the foul demon that stands at its heart. Finally, confront Prince Tortheldrin in Athenaeum.  Return to the Shen'dralar Ancient in the courtyard should you complete this quest."]="你必須消滅 5 塔周圍的守護者，這些塔為伊莫塔爾監獄提供動力。一旦水晶塔斷電，伊莫塔爾周圍的力場就會消散。  進入伊莫塔爾監獄並剷除監獄中心的邪惡惡魔。最後，在雅典娜神廟與託塞德林王子對峙。  如果你完成了這個任務，就回到庭院裡的申德拉拉古樹那裡。",
["You must find the blue dragonflight drake champion, Scryer, and slay him. Pry his skull from his corpse and return it to Emberstrife.  You know that Scryer can be found in Winterspring."]="你必須找到藍龍軍團的龍族冠軍占星者並殺死他。從屍體上撬開他的頭骨並將其歸還給安伯斯特萊夫。  你知道占星者可以在冬泉谷找到。",
["Young Crocolisk"]="年輕鱷魚",
["Young Riptooth"]="年輕的裂牙",
["Your tallstrider kicks up an abrasive cloud of dust, reducing the target's Armor for 30 sec."]="你的高陸行鳥會揚起一團磨蝕性的塵埃雲，降低目標的護甲值，持續 30 秒。",
["Yuka Screwspigot"]="尤卡·螺絲釘",
["Zarla's Snack Pouch"]="扎拉的零食袋",
["Zaruk"]="扎魯克",
["Zephras Isle"]="澤弗拉斯島",
["Zerril Softbreeze"]="澤里爾·軟風",
["Zor'la"]="佐拉",
["Zul'Gurub"]="祖爾格拉布",
["Zul'Gurub (Raid)"]="祖爾格拉布（團隊）",
["trainer"]="教練員",
["wild"]="荒野",
["Opens the doors of the Armory and the Cathedral. Anyone in the group who has it can open them."]="開啟血色修道院軍械庫和大教堂的大門。隊伍中任何持有鑰匙的成員都可以開門。",
["Opens the gate of Scholomance in Caer Darrow. Made by Krinkle Goodsteel in Gadgetzan from Imbued Skeletal Fragments; the last step is a quest for your faction."]="開啟凱爾達隆通靈學院的大門。加基森的克林科·古德斯迪爾使用灌魔骨片製作鑰匙；最後一步是陣營任務。",
["Opens the door to Upper Blackrock Spire. Collect the Unadorned Seal and three gemstones in Lower Blackrock Spire, then forge the seal at the dragon in Dustwallow Marsh."]="開啟黑石塔上層的大門。在黑石塔下層收集原始晉升印章和三顆寶石，然後前往塵泥沼澤找巨龍鍛造印章。",
["Opens the doors of Dire Maul West and North (also the Gordok side door). One key holder in the group is enough."]="開啟厄運之槌西區和北區的大門，也可開啟戈多克側門。隊伍中一人持有即可。",
["Opens the Shadowforge gates in Blackrock Depths (a shortcut; without it the doors need a rogue or Seeping Flames)."]="開啟黑石深淵的暗爐大門，提供一條捷徑；沒有鑰匙時需要盜賊開鎖或使用滲透之焰。",
["Opens the prison cells in the Detention Block (Jail Break!)."]="開啟拘留區的牢房，用於“衝破牢籠”任務。",
["Opens the gates between the two halves of Stratholme. Both gates can be entered without it."]="開啟斯坦索姆兩部分之間的大門。沒有鑰匙也能從各自入口進入。",
["Opens the Workshop side entrance and doors inside Gnomeregan."]="開啟諾莫瑞根車間側門及副本內部的門。",
["Opens the portal from the Maraudon entrance straight to Princess Theradras' falls."]="開啟傳送門，從瑪拉頓入口直達瑟萊德絲公主所在的瀑布。",
["Not needed to enter. Tunk drops the Krol'dok Mould inside the dungeon; a smith in Farholde Keep (Alliance) or Rog'mar (Horde) turns it into the key for 4 Thick Leather and 12 Iron Bars."]="進入副本不需要這把鑰匙。副本內的吞克掉落克羅多克模具；聯盟可找法奧迪爾要塞的鐵匠，部落可找羅格瑪，使用 4 塊厚皮和 12 塊鐵錠製作鑰匙。",
["Needed to enter Onyxia's Lair. Each faction earns it at the end of a long quest chain that starts around level 50 (Alliance) or 55 (Horde) and leads through Blackrock Spire."]="進入奧妮克希亞的巢穴需要此物品。聯盟約 50 級、部落約 55 級可開始各自的長任務鏈，任務途中需要前往黑石塔。",
["The spies near Ironband's Compound carry the map"]="鐵環挖掘場附近的間諜攜帶地圖。",
["Hands out the Gordok Tribute after King Gordok falls; the more guards alive, the better."]="戈多克國王倒下後，此人會分發戈多克貢品；存活的守衛越多，貢品越好。",
["Summoned by warlocks with the Dreadsteed quest."]="術士進行恐懼戰馬任務時召喚。",
["New Forever dungeon: I'lalai, a lost troll city that has risen from the sea. Naga, risen trolls and stranded pirates fight over its ruins. Its loot is still being discovered: what players have recorded so far is listed."]="《永恆》新地城：伊拉萊，一座從海中升起的失落巨魔城市。納迦、復生的巨魔和受困的海盜正在爭奪遺蹟。掉落仍在探索中，此處列出玩家目前記錄的物品。",
["A WoW Forever dungeon: a dig site in the Wetlands where something better left buried has been unearthed. Few boss kills recorded so far."]="《永恆》新地城：溼地的一處挖掘場，人們挖出了原本不該重見天日的東西。目前首領擊殺記錄較少。",
["The former gnome capital, flooded with radiation and taken over by troggs and the traitor Mekgineer Thermaplugg."]="曾經的侏儒首都，如今被輻射淹沒，遭穴居人和叛徒麥克尼爾·瑟瑪普拉格佔據。",
["Source of the Grime-Encrusted Ring. Forever loot table not known yet."]="掉落髒兮兮的戒指。《永恆》中的掉落列表尚不明確。",
["Grave robbers have forced their way into the old burial halls of the dwarven kings deep below Ironforge."]="盜墓者闖入了鐵爐堡深處的古代矮人國王陵墓。",
["New Forever dungeon: a Twilight's Hammer ogre fortress on a hill in the Riverglades. The ogres raid nearby settlements and take prisoners. Its loot is still being discovered."]="《永恆》新地城：暮光之錘的食人魔要塞，位於河谷林地的一座山丘上。食人魔襲擊附近的定居點並抓走囚犯，掉落仍在探索中。",
["The lower halls of Blackrock Spire, held by the Blackrock orcs, Firebrand Legion and Smolderthorn trolls. Overlord Wyrmthalak commands them."]="黑石塔下層由黑石獸人、火印軍團和燃棘巨魔佔據，指揮官是維姆薩拉克。",
["Summoned with the quest Urok Doomhowl."]="透過“烏洛克”任務召喚。",
["The sacred caverns of the centaur and the resting place of Zaetar. His corrupted daughter, Princess Theradras, waits at the bottom of the Earth Song Falls."]="半人馬的神聖洞穴，也是扎爾塔的安息之地。他被腐化的女兒瑟萊德絲公主在地歌瀑布深處等待。",
["The Fifth Khan, a spirit in the orange wing. Part of The Pariah's Instructions."]="第五可汗，橙色區域的靈魂；“賤民的指引”任務的一部分。",
["The Fourth Khan, a spirit in the purple wing. Part of The Pariah's Instructions."]="第四可汗，紫色區域的靈魂；“賤民的指引”任務的一部分。",
["A volcanic cave system under Orgrimmar, where troggs and the Burning Blade cult plot against the Horde."]="奧格瑞瑪地下的火山洞穴，穴居人和火刃教派在此密謀對付部落。",
["The quilboar's thorny burial grounds, now in the hands of the Scourge. Amnennar the Coldbringer leads the Death's Head from the depths."]="野豬人的荊棘墓地，如今被天災軍團佔據。寒冰之王亞門納爾在深處統領亡首部族。",
["A maze of giant thorn vines and the home of the quilboar. Charlga Razorflank leads her tribe from deep inside."]="巨型荊棘構成的迷宮，也是野豬人的家園。卡爾加·刺肋在深處統領部族。",
["The fallen human capital above the Undercity. Scourge remnants roam the streets and a necromancer is gathering strength in the ruins."]="幽暗城上方的毀滅人類都城。天災殘部徘徊在街道上，一名亡靈法師正在廢墟中積蓄力量。",
["Rare. Does not always spawn."]="稀有首領，不一定重新整理。",
["The Cult of the Damned's school of necromancy in the crypts beneath Caer Darrow. Darkmaster Gandling teaches the dark arts. Needs the Skeleton Key."]="凱爾達隆地下墓穴中的詛咒教派通靈學校。黑暗院長加丁在此傳授黑暗魔法。進入需要骸骨鑰匙。",
["Summoned in the Great Ossuary for the paladin and shaman class quests."]="聖騎士和薩滿祭司職業任務中，在大墓室召喚。",
["A haunted castle in Silverpine Forest, taken over by the mad archmage Arugal and the worgen he summoned."]="銀松森林中的鬧鬼城堡，已被瘋狂的大法師阿魯高及其召喚的狼人佔據。",
["Only during a seasonal event (Hallow's End)."]="僅在萬聖節活動期間出現。",
["New Forever dungeon: titan terraces, power crystals and ancient wildlife in the hills of Un'Goro Crater. Its loot is still being discovered."]="《永恆》新地城：安戈洛環形山丘陵中的泰坦平臺，遍佈能量水晶和古老生物。掉落仍在探索中。",
["The Scarlet Crusade's training grounds and armory, where Herod, the Scarlet Champion, drills his recruits. The door needs the Scarlet Key from the Library."]="血色十字軍的訓練場和軍械庫，血色勇士赫洛德在此訓練新兵。大門需要從圖書館獲得的血色鑰匙。",
["The heart of the Scarlet Monastery. Scarlet Commander Mograine and High Inquisitor Whitemane lead the Crusade from the cathedral. The door needs the Scarlet Key from the Library."]="血色修道院的核心。血色十字軍由大教堂中的指揮官莫格萊尼和大檢察官懷特邁恩領導。大門需要從圖書館獲得的血色鑰匙。",
["The monastery cemetery, where the Scarlet Crusade buries its fallen - and where the dead do not stay quiet."]="修道院的墓地，血色十字軍在此埋葬死者，而死者並不安寧。",
["Only during the Scourge Invasion event."]="僅在天災入侵活動期間出現。",
["The Crusade's library and archive. Several quests ask you to bring back books kept here."]="血色十字軍的圖書館和檔案館。數個任務需要取回這裡儲存的書籍。",
["Stormwind's prison under the Mage Quarter. The inmates have revolted and Bazil Thredd's Defias now hold the cell blocks."]="暴風城法師區地下的監獄。囚犯已經暴動，巴基爾·斯瑞德的迪菲亞手下佔據了牢區。",
["His hand is needed for Crime and Punishment."]="“罪與罰”任務需要他的手。",
["His head is needed for The Fury Runs Deep."]="“怒火深淵”任務需要他的頭顱。",
["The fallen city of Stratholme. The Scarlet Crusade holds the bastion behind the main gate, Baron Rivendare and the Scourge rule the ziggurats behind the service gate."]="毀滅的斯坦索姆城。血色十字軍佔據正門後的堡壘，瑞文戴爾男爵和天災軍團統治後門另一側的通靈塔。",
["Grand Crusader Dathrohan turns into the dreadlord Balnazzar during the fight."]="戰鬥中，大十字軍戰士達索漢會變身為恐懼魔王巴納扎爾。",
["The sunken temple of the Atal'ai trolls, who try to summon their god Hakkar. The green dragonflight guards the lower halls against them."]="阿塔萊巨魔的沉沒神廟，巨魔試圖召喚他們的神哈卡。綠龍軍團守衛著神廟下層，阻止他們。",
["Six troll minibosses on the balcony around the central hall: Zolo, Gasher, Loro, Hukku, Zul'Lor and Mijan."]="中央大廳周圍陽臺上的六名巨魔小首領：祖羅、加什爾、洛若爾、胡庫、祖羅爾和米杉。",
["An ancient titan vault in the Badlands, dug up by the Explorers' League and the Dark Iron dwarves. Archaedas guards the Discs of Norgannon."]="荒蕪之地的古代泰坦寶庫，由探險者協會和黑鐵矮人挖掘。阿扎達斯守護著諾甘農圓盤。",
["One of the Lost Dwarves, together with Eric \"The Swift\" and Olaf."]="失蹤的矮人之一，同行的還有“疾步者”埃裡克和奧拉夫。",
["The upper spire of the Black Dragonflight. Warchief Rend Blackhand rides from the Hordemar City arena, and General Drakkisath guards the way to Blackwing Lair. Needs the Seal of Ascension. In Forever a 10-player dungeon."]="黑龍軍團佔據的黑石塔上層。大酋長雷德·黑手從黑手大廳競技場出戰，達基薩斯將軍守衛著通往黑翼之巢的道路。進入需要晉升印章；《永恆》中為 10 人地城。",
["Summoned in the Rookery when an egg hatches."]="龍蛋孵化時在孵化室召喚。",
["A cave network in the Barrens where the druid Naralex lies in a nightmare and his former disciples have turned against nature."]="貧瘠之地的洞穴網路，德魯伊納拉雷克斯陷於噩夢，昔日的門徒也背離了自然。",
["The sun-baked capital of the Sandfury trolls in northern Tanaris. Chief Ukorz Sandscalp rules from the city, and Gahz'rilla sleeps in its sacred pool."]="塔納利斯北部砂怒巨魔的都城。酋長烏克茲·沙頂統治著城市，加茲瑞拉沉睡在聖池中。",
["Fights you on the temple stairs after the prisoner event."]="囚犯事件結束後在神廟階梯上與你戰鬥。",
["Summoned at the pool with the Mallet of Zul'Farrak."]="在水池處使用祖爾法拉克之槌召喚。",
["Carries the Executioner's Key for the prisoner cages."]="攜帶可開啟囚籠的劊子手鑰匙。",
["Defeat Atrexis the Grave Knight in the City of Dalaran for Melisara in Tarren Mill."]="在達拉然城擊敗墓地騎士阿特雷西斯，然後向塔倫米爾的梅麗薩拉覆命。",
["Use the Moonsilver Blade to destroy Old-Fire Eye in Silverpine Forest."]="使用月銀之刃消滅銀松森林的老火眼。",
["Take the tablet etchings to Master Gadrin in Sen'jin Village in Durotar."]="把石板拓文帶給杜隆塔爾森金村的加德林大師。",
["Slay Var'Taka in the Drowned City."]="在沉沒之城擊殺瓦塔卡。",
["Recover an Ancient Gurubashi Idol from the Drowned City."]="從沉沒之城找回一尊古代古拉巴什神像。",
["Collect 10 Voodoo Infused Artifacts from Saltseer pirates in the Drowned City."]="從沉沒之城的鹽視海盜身上收集 10 件注入巫毒的神器。",
["Slay 3 Saltseer Coroners and Captain Dreadrise in the Drowned City."]="在沉沒之城擊殺 3 名鹽視驗屍官以及德瑞德瑞斯船長。",
["Bring the I'lalai Fetish to Abra Cadabra in Dalaran."]="將伊拉萊護符帶給達拉然的阿布拉·卡達布拉。",
["Bring Loremaster Dibbs' I'lalai Translations to Historian Karnik in Ironforge."]="將博學者迪布斯的伊拉萊譯文帶給鐵爐堡的歷史學家卡尼克。",
["Return to Caitlin Grassman in Menethil Harbor."]="回到米奈希爾港，向凱特琳·格拉斯曼覆命。",
["Return to Dorin Songblade."]="回去向多林·歌刃覆命。",
["Kill a Highland Horror within Excavation Sites and bring its root core to Rethiel the Greenwarden in the Wetlands."]="在挖掘場內擊殺高地恐魔，將它的根核帶給溼地的綠衣守護者雷希爾。",
["Bring the Titan Relic to High Explorer Magellas in Ironforge's Hall of Explorers."]="將泰坦遺物帶給鐵爐堡探險者大廳的首席探險家麥哲拉斯。",
["Bring the Titan Relic to Muln Earthfury at the Skywatcher Plateau in northwest Mulgore."]="將泰坦遺物帶給莫高雷西北部觀星者高地的穆恩·大地之怒。",
["Slay the Dragonmaw forces within the Excavation Site and return to the Deathstalker Agent outside with anything you recover."]="消滅挖掘場裡的龍喉部隊，將找到的物品交給外面的亡靈哨兵特工。",
["Enter the Excavation Sites in the Wetlands and bring back Thicket Raptor Meat."]="進入溼地的挖掘場，取回叢林迅猛龍肉。",
["Return 4 Thicket Raptor Hides to James Halloran, the tanner, in Menethil Harbor."]="將 4 張叢林迅猛龍皮交給米奈希爾港的制皮師詹姆斯·哈洛蘭。",
["Retrieve the Rig Blueprints and Thermaplugg's Safe Combination from Gnomeregan and bring them to Nogg in Orgrimmar. "]="從諾莫瑞根取回機械裝置藍圖和瑟瑪普拉格保險箱密碼，交給奧格瑞瑪的諾格。",
["Put the spirit of Faldrim Anvilmar to rest and then return to the Ghostly Attendant in the Hall of Thanes."]="安息法爾德林·安威瑪爾的靈魂，然後回到族長之廳找幽靈侍從。",
["Collect 8 Dwarven Heirlooms from the Hall of Thanes."]="從族長之廳收集 8 件矮人傳家寶。",
["Kill 15 Enraged Apparitions, 10 Tormented Souls and put the spirit of Anvilmar to rest."]="擊殺 15 個憤怒的幻影、10 個受折磨的靈魂，並安息安威瑪爾的靈魂。",
["Enter the Hall of Thanes beneath Old Ironforge and claim the Head of Durgen Dirgehammer."]="進入舊鐵爐堡下方的族長之廳，取得杜爾根·輓歌之錘的頭顱。",
["Deliver the Treaty of Understanding to Magni Bronzebeard in Ironforge."]="將諒解條約送給鐵爐堡的麥格尼·銅須。",
["Collect 15 Cultist Ears from the Twilight's Hammer in Krol'dok Stronghold."]="在克羅多克要塞收集 15 只暮光之錘教徒的耳朵。",
["Bring the Satchel of Mementos to Melanie Sable."]="將紀念品揹包交給梅蘭妮·塞布林。",
["Recover the Tome of Twilight from Krol'dok Stronghold."]="從克羅多克要塞取回暮光之書。",
["Kill Nar'gurk within Krol'dok Stronghold and recover any valuable information."]="擊殺克羅多克要塞裡的納古爾克，取回有價值的情報。",
["Infiltrate Krol'dok Stronghold and return to Krom'rosh with proof of their leader's demise."]="潛入克羅多克要塞，拿著首領被消滅的證明向克羅姆羅什覆命。",
["Infiltrate Krol'dok Stronghold and return to Commander Brant with proof of their leader's demise."]="潛入克羅多克要塞，拿著首領被消滅的證明向布蘭特指揮官覆命。",
["Travel to Krol'dok Stronghold and slay Zalfan Moonshadow."]="前往克羅多克要塞，擊殺扎爾凡·月影。",
["Travel to Blackrock Spire and collect 15 Spire Spider Eggs for Kibler.  By the sound of it, these eggs could be found near spiders. "]="前往黑石塔，為基布雷爾收集 15 枚尖塔蜘蛛卵。蜘蛛附近應該能找到這些卵。",
["Find Bijou's Belongings and return them to her. You recall her mentioning that she stashed them on the bottom floor of the city. "]="找到比修的物品並還給她。她曾提到把東西藏在城市的最底層。",
["Recover the crystal known as An'she's Radiance from Maraudon."]="從瑪拉頓找回被稱為安舍之光的水晶。",
["Escort Belnistrasz to the Quilboar's idol in Razorfen Downs.  Protect Belnistrasz while he performs the ritual to shut down the idol."]="護送貝爾尼斯特拉茲到剃刀高地的野豬人神像處。他進行關閉神像的儀式時保護他。",
["Collect the Head of the Baron in the Ruins of Lordaeron and bring it back to Captain Truman."]="在洛丹倫廢墟收集男爵的頭顱，帶回給杜魯曼隊長。",
["Deliver the Abominable Head to someone within the Undercity."]="將憎惡的頭顱交給幽暗城內的某人。",
["Investigate the disappearance of Edward Heartweaver in the Ruins of Lordaeron."]="調查洛丹倫廢墟中愛德華·織心的失蹤事件。",
["Collect 10 Bloodied Insignias and take them to General Marcus Jonathan in Stormwind City."]="收集 10 枚血跡斑斑的徽記，交給暴風城的馬庫斯·喬納森將軍。",
["Return the Crest of Lordaeron to Lady Dena Kennedy in Stormwind City."]="將洛丹倫紋章交給暴風城的迪娜·肯尼迪女士。",
["Bring the Crest of Lordaeron to Oran Snakewrithe in Undercity."]="將洛丹倫紋章交給幽暗城的奧蘭·蛇繞。",
["Collect 25 Intact Limbs within The Ruins of Lordaeron for Morbin Lightbane in the Undercity."]="在洛丹倫廢墟收集 25 條完整的肢體，帶給幽暗城的莫爾賓·光災。",
["Bring the Blood-Stained Letter to Orphan Matron Nightingale in Stormwind City."]="將血跡斑斑的信交給暴風城的孤兒院院長奈丁格爾。",
["Collect the Highly Toxic Strain from Witherfang in Ruins of Lordaeron for Theodore Griffs in Undercity."]="從洛丹倫廢墟的凋牙身上收集劇毒菌株，交給幽暗城的西奧多·格里夫斯。",
["Kill Rath'mael in the Ruins of Lordaeron for Deathguard Kristof in Brill."]="在洛丹倫廢墟擊殺拉斯邁爾，向布瑞爾的亡靈衛兵克里斯托弗覆命。",
["Bring Darkreaver's Head to Sagorne Creststrider in the Valley of Wisdom, Orgrimmar."]="將達克雷爾的頭顱帶給奧格瑞瑪智慧谷的薩戈尼·火角。",
["Bring Mayena Earthseeker a Moist Crystal, a Charged Crystal, a Noxious Crystal and a Fiery Crystal from Shaper's Terrace."]="從塑造者平臺取得潮溼水晶、充能水晶、劇毒水晶和熾熱水晶，交給瑪耶娜·尋地者。",
["Retrieve the book The Lost Magic of the Runemasters from the Scarlet Monastery."]="從血色修道院取回《符文大師的失落魔法》。",
["Find The Eye of Bhossca inside of the Scarlet Monastery. Then, return it to C's dead drop near Pyrewood Village. You must complete the job alone."]="在血色修道院找到波斯卡之眼，然後送到焚木村附近 C 的秘密投遞點。必須獨自完成。",
["Travel to Stratholme and search the ziggurats. Find and return new Scourge Data to Betina Bigglezink. "]="前往斯坦索姆搜查通靈塔，找到新的天災軍團資料並交給貝蒂娜·比格辛克。",
["Find Ezra Grimm's smoke shop in Stratholme and recover a box of Grimm's Premium Tobacco. Return to Smokey LaRue when the job is done. "]="在斯坦索姆找到埃茲拉·格瑞姆的菸草店，取回一盒格瑞姆的優質菸草，然後交給斯莫奇·拉魯。",
["Venture to Stratholme and destroy Baron Rivendare. Take his head and return to Duke Nicholas Zverenhoff. "]="前往斯坦索姆消滅瑞文戴爾男爵，將其頭顱交給尼古拉斯·瑟倫霍夫公爵。",
["Travel to Stratholme and kill the Crimson Hammersmith. Recover the Crimson Hammersmith's Apron and return to Lilith. "]="前往斯坦索姆擊殺紅衣鑄錘師，取回他的圍裙交給莉莉絲。",
["Travel to Blackrock Spire and destroy General Drakkisath. Return to Marshal Maxwell when the job is done. "]="前往黑石塔消滅達基薩斯將軍，然後向麥克斯韋爾元帥覆命。",
["That is one stupid orc. It would appear as if you need to find this brand and gain the Mark of Drakkisath in order to access the Orb of Command.  The letter indicates that General Drakkisath guards the brand. Perhaps you should investigate."]="為了使用命令寶珠，你需要找到烙印並獲得達基薩斯印記。信中說達基薩斯將軍守護著烙印，去調查一下。",
["Travel to Ratchet to find someone that can tell you more about the glowing shard.  Then, deliver the shard as you are directed."]="前往棘齒城尋找能解釋發光碎片的人，然後按指示送交碎片。",
["New Forever raid for 20 players, opening on 9 December 2026: snowy peaks, ancient elven ruins and ghosts of the Third War. Something drains the power of the land around the summit. Loot and quests are not known yet."]="《永恆》新增 20 人團隊副本，於 2026 年 12 月 9 日開放。這裡有白雪覆蓋的山峰、古代精靈遺蹟和第三次戰爭的幽靈；某種力量正在汲取山巔附近的大地之力。掉落和任務尚不明確。",
["The lair of the black dragon Onyxia, deep in the Wyrmbog of Dustwallow Marsh. A raid for 40 players, opening on 9 December 2026. You need the Drakefire Amulet to enter (see Attunement). The loot list holds the drops known so far; the full table follows once the raid is open."]="黑龍奧妮克希亞的巢穴，位於塵泥沼澤的巨龍沼澤深處。40 人團隊副本，於 2026 年 12 月 9 日開放。進入需要龍火護符，任務鏈見入場任務。此處列出目前已知掉落，完整掉落待副本開放後補充。",
["Travel to Dire Maul and locate the Imp, Pusillin. Convince Pusillin to give you Azj'Tordin's Book of Incantations through any means necessary.  Return to Azj'Tordin at the Lariss Pavilion in Feralas should you recover the Book of Incantations."]="前往厄運之槌找到小鬼普希林，想辦法讓他交出埃瑟裡克的咒術之書。找到書後，回菲拉斯的拉瑞斯小亭交給埃瑟裡克。",
["Find the Gauntlet of Gordok Might and return it to Captain Kromcrush in Dire Maul.  According to Kromcrush, the \"old timey story\" says that Tortheldrin - a \"creepy\" elf who called himself a prince - stole it from one of the Gordok kings."]="找到戈多克力量護手，交給厄運之槌的克羅卡斯隊長。他說古老的故事中，聲稱自己是王子的古怪精靈託塞德林從一位戈多克國王手中偷走了它。",
["Travel to Gnomeregan and bring back High Potency Radioactive Fallout. Be warned, the fallout is unstable and will collapse rather quickly.  Ozzie will also require your Heavy Leaden Collection Phial when the task is complete. "]="前往諾莫瑞根取回高輻射塵。輻射塵不穩定，會很快消散；完成任務時奧茲還需要你的重鉛收集瓶。",
["Fill the Coated Cerulean Vial at the orange crystal pool in Maraudon.  Use the Filled Cerulean Vial on the Vylestem Vines to force the corrupted Noxxious Scion to emerge.  Heal 8 plants by killing these Noxxious Scion, then return to Vark Battlescar in Shadowprey Village."]="在瑪拉頓的橙色水晶池裝滿塗層碧藍瓶，對邪刺之藤使用裝滿的瓶子，讓被腐化的諾克賽恩產物現身。擊殺它們以治癒 8 株植物，然後向葬影村的瓦克·戰痕覆命。",
["Fill the Coated Cerulean Vial at the orange crystal pool in Maraudon.  Use the Filled Cerulean Vial on the Vylestem Vines to force the corrupted Noxxious Scion to emerge.  Heal 8 plants by killing these Noxxious Scion, then return to Talendria in Nijel's Point."]="在瑪拉頓的橙色水晶池裝滿塗層碧藍瓶，對邪刺之藤使用裝滿的瓶子，讓被腐化的諾克賽恩產物現身。擊殺它們以治癒 8 株植物，然後向尼耶爾前哨站的塔琳德莉亞覆命。",
["Grab a Crate with Holes. Grab a Snufflenose Command Stick. Grab and read the Snufflenose Owner's Manual.  In Razorfen Kraul, use the Crate with Holes to summon a Snufflenose Gopher, and use the Command Stick on the gopher to make it search for Tubers.  Bring 6 Blueleaf Tubers, the Snufflenose Command Stick and the Crate with Holes to Mebok Mizzyrix in Ratchet."]="取得一個有孔的箱子、一根土撥鼠指揮棒，閱讀土撥鼠使用手冊。在剃刀沼澤使用箱子召喚土撥鼠，再對它使用指揮棒搜尋塊莖。把 6 個藍葉薯、指揮棒和箱子交給棘齒城的麥伯克·米希瑞克斯。",
["Find Doctor Theolen Krastinov inside the Scholomance. Destroy him, then burn the Remains of Eva Sarkhoff and the Remains of Lucien Sarkhoff. Return to Eva Sarkhoff when the task is complete. "]="在通靈學院找到並消滅瑟爾林·卡斯迪諾夫教授，然後焚燒伊瓦·薩克霍夫和盧森·薩克霍夫的遺骸。完成後向伊瓦覆命。",
["Return to the Scholomance with the Blood of Innocents. Find the porch and place the Blood of Innocents in the brazier. Kirtonos will come to feast upon your soul.  Fight valiantly, do not give an inch! Destroy Kirtonos and return to Eva Sarkhoff. "]="帶著無辜者之血回到通靈學院，找到陽臺並把血放入火盆。基爾圖諾斯會前來，擊敗他後向伊瓦·薩克霍夫覆命。",
["Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance. Doing so will bring forth the spirits you must judge. Defeating these spirits will summon forth Death Knight Darkreaver. Defeat him and reclaim the lost soul of the fallen charger.  Give the Charger's Redeemed Soul and the Blessed Enchanted Barding to Darkreaver's Fallen Charger."]="在通靈學院大墓室地下深處使用占卜法杖，引出需要審判的靈魂。擊敗這些靈魂後，死亡騎士達克雷爾會現身。擊敗他並找回戰馬失落的靈魂，將救贖之魂和祝福過的奧金馬鎧交給達克雷爾的墮落戰馬。",
["Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance. Doing so will bring forth spirits you must fight. Defeating these spirits will summon forth Death Knight Darkreaver; defeat him.  Bring Darkreaver's Head to Sagorne Creststrider in the Valley of Wisdom, Orgrimmar."]="在通靈學院大墓室地下深處使用占卜法杖，引出並擊敗靈魂，召喚並消滅死亡騎士達克雷爾。將他的頭顱帶給奧格瑞瑪智慧谷的薩戈尼·火角。",
["Use Egan's Blaster on the ghostly and spectral citizens of Stratholme. When the restless souls break free from their ghostly shells, use the blaster again - freedom will be theirs!  Free 15 Restless Souls and return to Egan."]="對斯坦索姆的幽靈居民使用艾根的衝擊器；不安的靈魂脫離軀殼後再使用一次，使其獲得自由。釋放 15 個不安的靈魂，向艾根覆命。",
["Travel to Stratholme, in the northern part of the Plaguelands. It is in the Scarlet Bastion that you will find the painting 'Of Love and Family,' hidden behind another painting depicting the twin moons of our world.  Return the painting to Tirion Fordring."]="前往瘟疫之地北部的斯坦索姆，在血色區尋找畫作《愛與家庭》；它藏在一幅描繪雙月的畫後面。將畫交給提里奧·弗丁。",
["Recover all three gems and a power source for the necklace from Uldaman, and then bring them to Jarkal Mossmeld in Kargath. Jarkal believes a power source might be found on the strongest construct present in Uldaman.  From the journal, you know... * The ruby has been stashed in a barricaded Shadowforge area. * The topaz has been hidden in an urn in one of the Trogg areas, near some Alliance dwarves. * The sapphire has been claimed by Grimlok, the trogg leader."]="在奧達曼找到項鍊所需的 3 顆寶石和一個能量源，交給卡加斯的加卡爾·苔痕。他認為能量源可能在奧達曼最強大的構造體身上。根據日記：紅寶石藏在設有路障的暗爐區域；黃寶石藏在穴居人區域、聯盟矮人附近的骨灰甕裡；藍寶石在穴居人首領格瑞姆洛克手中。",
["Travel to Blackrock Spire and find Goraluk Anvilcrack. Slay him and then use the Blood Stained Pike upon his corpse. After his soul has been siphoned, the pike will be Soul Stained.  You must also find the Unforged Rune Covered Breastplate.  Return both the Soul Stained Pike and the Unforged Rune Covered Breastplate to Lorax in Winterspring."]="前往黑石塔找到並擊殺古拉魯克·安威克拉克，對他的屍體使用染血長矛，吸取靈魂後長矛會變為浸血長矛。還要找到未鑄造的符文胸甲，將兩件物品交給冬泉谷的羅拉克斯。",
["New Forever dungeon: a Defias prison on Alcaz Island where nobles were held for ransom, and rumour says Varian Wrynn was one of them. Now the Defias fight the naga inside. Its loot is still being discovered."]="《永恆》新地城：奧卡茲島上的迪菲亞監獄，貴族曾被囚禁在這裡等待贖金，據傳瓦里安·烏瑞恩也是其中之一。如今迪菲亞在監獄內與納迦交戰；掉落仍在探索中。",
["New Forever raid for 10 players, opening on 9 December 2026: the barrow dens where the night elves keep their most dangerous prisoners, now touched by spreading corruption. One of its entrances lies on Mount Hyjal. Loot and quests are not known yet."]="《永恆》新增 10 人團隊副本，於 2026 年 12 月 9 日開放。暗夜精靈曾在地穴關押最危險的囚犯，如今腐化正在這裡蔓延。其中一個入口位於海加爾山；掉落和任務尚不明確。",
["Leader of the Seven; the Chest of The Seven opens after the fight."]="七賢之首；戰鬥結束後可開啟七賢寶箱。",
["A WoW Forever dungeon inside the shielded city of Dalaran. Boss loot has not been recorded yet."]="位於護盾籠罩下的達拉然城內的《永恆》地城，首領掉落尚無記錄。",
["Rare spawn; if he is up, you find him in the tunnel branching off after the first boss."]="稀有首領。如果已重新整理，可以在第一個首領之後的岔路隧道找到他。",
["Gordok Commons, taken over by the Gordok ogres. Kill King Gordok and Captain Kromcrush makes you the new king, but leave the guards alive for a richer tribute."]="被戈多克食人魔佔據的戈多克廣場。擊敗戈多克大王和克羅卡斯隊長後你會成為新國王；讓其他守衛存活可獲得更豐厚的貢品。",
["The Capital Gardens of Eldre'Thalas, where the last Highborne of the Shen'dralar feed on the demon Immol'thar. Prince Tortheldrin rules from the library."]="厄雷薩拉斯的都城花園。辛德拉最後的上層精靈汲取惡魔伊莫塔爾的力量；託塞德林王子在圖書館統治這裡。",
["Gillijim's Isle, off the coast of Stranglethorn Vale"]="荊棘谷近海的吉利吉姆島",
["Ironforge, under the city"]="鐵爐堡地下",
["Riverglades"]="河谷林地",
["Orgrimmar, Cleft of Shadow"]="奧格瑞瑪，暗影裂口",
["Southern Barrens, near Thousand Needles"]="貧瘠之地南部，千針石林附近",
["Southern Barrens"]="貧瘠之地南部",
["Tirisfal Glades, Ruins of Lordaeron"]="提瑞斯法林地，洛丹倫廢墟",
["Caer Darrow, Western Plaguelands"]="西瘟疫之地，凱爾達隆",
["Silverpine Forest, above Pyrewood Village"]="銀松森林，焚木村上方",
["Scarlet Monastery, Tirisfal Glades"]="提瑞斯法林地，血色修道院",
["Tirisfal Glades, Scarlet Monastery"]="提瑞斯法林地，血色修道院",
["The Barrens, north of the Crossroads"]="貧瘠之地，十字路口以北",
["The part inside the dungeon. Its reward comes two steps later with Curios of Curiosity (Lingering Essence, then Curios of Curiosity - both outside)."]="這是副本內的部分。完成後還要進行兩步才能獲得“奇異之物”的獎勵：先做“殘留的精華”，再做“奇異之物”；兩步都在副本外。",
["No dungeon objective: the last step after Twilight Mementos, done outside in Farholde Keep - it gives that chain's reward."]="沒有副本內目標：這是“暮光紀念品”之後的最後一步，在副本外的法奧迪爾要塞完成，並獲得該任務鏈的獎勵。",
["Ironband's Compound (Dark Iron Spies)"]="鐵環營地（黑鐵間諜）",
["Quell The Uprising"]="平息叛亂",
["The Great Ezra Grimm"]="偉大的埃茲拉·格瑞姆",
["Pip Quickwit, At Your Service!"]="機智的皮普，聽候差遣！",
["Abominable Head"]="憎惡的頭顱",
["Abra Cadabra"]="阿布拉·卡達布拉",
