["Fight through Scarlet Monastery: Library to Arcanist Doan."]="穿過血色修道院圖書館，找到奧法師杜安。",
["Loot The Scarlet Key from the strongbox behind Arcanist Doan. It stays in your keyring."]="從奧法師杜安身後的保險箱中拾取血色鑰匙，它會放入鑰匙鏈。",
["Set the North, South, East, and West Sentry Towers on fire by using the Torch of Retribution inside each of the buildings.  "]="在北、南、東、西四座哨塔的建築內使用懲戒火炬，將它們點燃。",
["Gather 10 Nordrassil Root Caps inside Blackmaw Hold for Nara Wildmane in Thunder Bluff."]="在黑喉要塞中收集 10 個諾達希爾根鬚，交給雷霆崖的納拉·蠻鬃。",
["Gather 10 Nordrassil Root Caps inside Blackmaw Hold for Mathrengyl Bearwalker in Darnassus."]="在黑喉要塞中收集 10 個諾達希爾根鬚，交給達納蘇斯的瑪斯雷·馭熊者。",
["Collect the Founding of Dalaran from the City of Dalaran for Rexxie Copperclutch near the sewer entrance."]="從達拉然城取回《達拉然的建立》，交給下水道入口附近的雷克西·銅鉗。",
["Defeat 8 Seeking Remnants, 8 Saturated Remnants, and 8 Mana Echoes inside the City of Dalaran for Archmage Modera outside of Dalaran."]="在達拉然城內擊敗 8 個搜尋殘影、8 個飽和殘影和 8 個法力迴響，向城外的大法師莫德拉覆命。",
["Use the Well Water Sample Kit to collect samples from the wells at the Jansen Stead and the Molsen Farm."]="使用井水取樣工具，從詹森農場和摩爾森農場的井裡採集樣本。",
["Slay 4 Kobold Diggers in the Jangolode Mine and 6 Riverpaw Miners in the Gold Coast Quarry."]="在詹戈洛德礦井擊殺 4 個狗頭人挖掘工，並在金海岸礦場擊殺 6 個河爪礦工。",
["Collect 8 Suspicious Industrial Supplies from Moonbrook."]="在月溪鎮收集 8 份可疑工業用品。",
["Obtain 10 Rough Dynamite from crafting, trading, or the auction house, then return to Sprite Jumpsprocket in the Dwarven District of Stormwind."]="透過製作、交易或拍賣行取得 10 個劣質炸藥，然後返回暴風城矮人區找斯普萊特·彈簧齒輪。",
["Bring the Remote Detonator Kit to Sprite Jumpsprocket in the Dwarven District of Stormwind."]="將遙控引爆器套件交給暴風城矮人區的斯普萊特·彈簧齒輪。",
["Find Commander Gor'shak in Blackrock Depths.  You recall that the crudely drawn picture of the orc included bars drawn over the portrait. Perhaps you should search for a prison of some sort."]="在黑石深淵找到指揮官戈沙克。你記得那張粗糙的獸人畫像上還畫有柵欄，也許應該找找監牢。",
["Permanently enchants a weapon with a chance while casting to grant Insight, increasing Spirit by 100% for 10 sec."]="永久附魔武器：施法時有機率獲得洞察效果，使精神提高 100%，持續 10 秒。",
