-- 6.2.13 interface additions
["Last scan here: %s ago"]="此處上次掃描：%s前",
["Ready again in about %s."]="約%s後可再次掃描。",
["Cheap Upgrade Scan complete: %d items scanned."]="低價升級掃描完成：已掃描%d件物品。",
["Cheap Upgrade Scan"]="低價升級掃描",
["The prices are used by Armory > Gear Planner > Cheap Upgrades."]="價格用於軍械庫 > 裝備規劃 > 低價升級。",
["Scan %d%%"]="掃描%d%%",
["Blizzard allows a full scan only once every 15 minutes, for all addons together. A full scan of another addon is read along."]="暴雪限制所有外掛共用一次完整掃描，每15分鐘只能進行一次；其他外掛發起的完整掃描也會讀取。",
["Scan..."]="掃描中……",
["No scan here yet."]="此處尚無掃描記錄。",
["Can be switched off: Quality of Life > Loot & Vendors."]="可在便利功能 > 拾取與商人中關閉。",
["The auction house allows a full scan only every 15 minutes - try again later."]="拍賣行每15分鐘只能完整掃描一次，請稍後重試。",
["Reads the whole auction house and keeps the cheapest price of every Bind on Equip piece of gear - items with a random bonus (\"of the Eagle\", \"of the Bear\" ...) each with their own price. Auctionator keeps only one price per item, whatever its bonus."]="讀取整個拍賣行，記錄每件裝備後繫結裝備的最低一口價；隨機屬性裝備按每種屬性分別記錄。Auctionator 對同一物品只記錄一個價格。",
["Item against item"]="單件對比",
["Everything in your bags is worth as much or more."]="揹包裡的物品價值都不低於此物。",
["This loot is not worth more than anything in your bags."]="這件戰利品不比揹包裡的物品更值錢。",
["Whole gear"]="全身裝備",
["Spell Penetration"]="法術穿透",
["Max price"]="最高價格",
["Pre Raid"]="團本前",
["BiS List"]="畢業裝備清單",
["Needs auction house prices: click \"Cheap Upgrade Scan\" in the auction house (or use Auctionator)."]="需要拍賣行價格：請在拍賣行點選“低價升級掃描”，或使用 Auctionator。",
["Cheap Upgrades"]="低價升級",
["Shockadin"]="震擊騎",
["The best items per slot before raids (\"Pre Raid\") from wowtbc.gg's WoW Forever BiS lists, checked daily. BiS = their pick for the slot, the others are good alternatives. More lists come later."]="來自 wowtbc.gg 的《魔獸世界：永恆》團本前畢業裝備清單，每個部位標出推薦裝備和其他備選。以後會增加更多清單。",
["No BiS list for this spec yet."]="此專精暫時沒有畢業裝備清單。",
["Click \"Cheap Upgrade Scan\" in the auction house for fresh prices. Scans older than 3 days are not used - then the prices come from Auctionator."]="在拍賣行點選“低價升級掃描”獲取最新價格。超過3天的掃描結果不會使用，屆時改用 Auctionator 的價格。",
["Expertise"]="精準",
["Feral DPS"]="野性輸出",
["BiS"]="畢業推薦",
["Feral Tank"]="野性坦克",
["No cheap upgrade up to %s for this in your level range.\nClick \"Cheap Upgrade Scan\" in the auction house for fresh prices, or raise the highest price."]="你的等級範圍內沒有價格不超過%s的升級裝備。\n請在拍賣行點選“低價升級掃描”獲取最新價格，或提高最高價格。",
["Cheap Upgrades: %s"]="低價升級：%s",
