["(overall %s%%)"]="（全身%s%%）",
["(worn item has no value for you)"]="（已裝備的物品對你沒有評分）",
["Upgrade (worn item has no value for you)"]="提升（已裝備的物品對你沒有評分）",
["Group invites, duels and recipe sharing."]="組隊邀請、決鬥和配方分享。",
["Battlemaster"]="戰場軍官",
["Opens the vendor, bank, trainer ... window at once."]="直接開啟商人、銀行或訓練師等服務視窗。",
["Which change in % the tooltip line shows."]="選擇滑鼠提示中顯示哪種百分比變化。",
