["Trainers"]="訓練師",
["Bags, windows, the minimap and other helpers for the game's interface."]="揹包、視窗、小地圖及其他介面輔助功能。",
["Gear Value shows"]="裝備評分顯示",
["Skip the talk at service NPCs"]="跳過服務NPC的對話",
["Reads the whole auction house (Blizzard's full scan, once every 15 minutes) and keeps the cheapest price of every Bind on Equip piece of gear, items with a random bonus (\"of the Eagle\") each with their own price - Auctionator has only one price per item. Off: no button, nothing is read; the Cheap Upgrades then use Auctionator's prices."]="完整掃描拍賣行，記錄各裝備後繫結裝備的最低一口價；隨機屬性裝備按屬性分別記錄。暴雪限制每15分鐘一次完整掃描。關閉後不顯示按鈕也不讀取拍賣行，低價升級將使用 Auctionator 的價格。",
["Guild Tabard"]="公會戰袍商人",
["Guild Bank"]="公會銀行",
["%d of %d"]="%d / %d",
["Whole gear: how much the item changes all the gear you wear. Item against item: against the item it replaces (bigger numbers). Both: \"65% (overall 6%)\". The arrows stay the same."]="全身裝備：換上物品後全身評分的變化。單件對比：與被替換物品的評分對比。兩者：同時顯示兩種變化。箭頭方向不變。",
["NPC shortcuts, the chat and other small helpers."]="NPC快捷服務、聊天和其他輔助功能。",
["Only when the NPC has no quests for you and offers just this one service. Hold Shift to talk normally. Tick the services in the list."]="僅當NPC沒有可接任務且只提供一項服務時生效。按住 Shift 可正常對話。請在列表中勾選服務。",
["NPCs"]="NPC",
["A button in the auction house that scans it for Armory > Cheap Upgrades."]="在拍賣行新增掃描按鈕，為軍械庫的低價升級提供價格。",
["Cheap Upgrade Scan button"]="低價升級掃描按鈕",
["Tick the services in the list."]="請在列表中勾選服務。",
["Stable Master"]="獸欄管理員",
["Shared: %s."]="已分享：%s。",
["Shared: %s. Click \"Share all Quests\" again for the next one (%d left)."]="已分享：%s。再次點選“分享所有任務”可分享下一項（還剩%d項）。",
["Your class and spec are picked at first, and every item shows where you get it. More lists will follow."]="預設選擇你的職業和專精，每件物品都顯示獲取途徑。後續會增加更多清單。",
["Armory > Gear Planner > BiS List: the best items per slot before raids for every class and spec, from the WoW Forever BiS lists of wowtbc.gg."]="軍械庫 > 裝備規劃 > 畢業裝備清單：檢視每個職業和專精的團本前推薦裝備，資料來自 wowtbc.gg。",
["Open Armory"]="開啟軍械庫",
["New stat weights"]="新裝備權重",
["Armory > Gear Planner > Cheap Upgrades: Bind on Equip gear from the auction house that improves your gear, up to a highest price you set."]="軍械庫 > 裝備規劃 > 低價升級：按你設定的最高價格，尋找拍賣行中能提升裝備的裝備後繫結物品。",
["Click \"Cheap Upgrade Scan\" in the auction house: it reads all auctions, also items with a random bonus (\"of the Eagle\"), each with its own price."]="在拍賣行點選“低價升級掃描”，讀取所有拍賣物品；隨機屬性裝備按每種屬性分別記錄價格。",
["The Gear Value uses new stat weights for every class and spec (from Geared Forever)."]="裝備評分為各職業和專精使用新的權重，資料來自 Geared Forever。",
["Quality of Life > Tooltips > \"Gear Value shows\": the change for your whole gear, item against item, or both."]="便利功能 > 滑鼠提示 > “裝備評分顯示”：選擇全身變化、單件對比或同時顯示。",
["Atal'ai statue %s"]="阿塔萊雕像%s",
["Use the six statues in this order (1 to 6) to summon Atal'alarion."]="依照1至6的順序使用六座雕像，召喚阿塔拉利恩。",
["%d min"]="%d分鐘",
["New dungeon maps"]="新增地城地圖",
["Open Dungeons"]="開啟地城",
["Dungeon maps are now available for Alcaz Prison, The Drowned City, Krol'dok Stronghold, Blackmaw Hold and Shaper's Terrace."]="新增奧卡茲監獄、沉沒之城、克羅多克要塞、黑喉要塞和塑造者露台地圖。",
["Switch floors on multi-level maps and click a boss to see its loot. Boss locations are approximate."]="多層地圖可切換樓層，點擊首領可查看戰利品。首領位置為近似值。",
